/// Plain-text render of `jet inspect reserved`.
pub fn reserved_report_text() -> String {
    let mut out = String::from("keywords:\n");
    for word in crate::Syntax::JET_KEYWORD_LIST {
        out.push_str(&format!("  {word}\n"));
    }
    out.push_str("\nteaching-reserved words (not valid identifiers):\n");
    for entry in TEACHING_RESERVED {
        out.push_str(&format!("  {:<10} {}\n", entry.spelling, entry.note));
    }
    out.push_str("\nsigils:\n");
    for entry in RESERVED_SIGILS {
        out.push_str(&format!("  {:<10} {}\n", entry.spelling, entry.note));
    }
    out
}

/// `--json` render of `jet inspect reserved`.
pub fn reserved_report_json() -> String {
    fn esc(s: &str) -> String {
        s.chars()
            .flat_map(|c| match c {
                '"' => "\\\"".chars().collect::<Vec<_>>(),
                '\\' => "\\\\".chars().collect(),
                c => vec![c],
            })
            .collect()
    }
    let keywords = crate::Syntax::JET_KEYWORD_LIST
        .iter()
        .map(|word| format!("\"{}\"", esc(word)))
        .collect::<Vec<_>>()
        .join(",");
    let render_entries = |entries: &[ReservedEntry]| {
        entries
            .iter()
            .map(|entry| {
                format!(
                    "{{\"spelling\":\"{}\",\"kind\":\"{}\",\"note\":\"{}\"}}",
                    esc(entry.spelling),
                    esc(entry.kind),
                    esc(entry.note)
                )
            })
            .collect::<Vec<_>>()
            .join(",")
    };
    let payload = format!(
        "{{\"keywords\":[{}],\"teaching_reserved\":[{}],\"sigils\":[{}]}}",
        keywords,
        render_entries(TEACHING_RESERVED),
        render_entries(RESERVED_SIGILS),
    );
    StatusEnvelope::new("inspect.reserved", true)
        .with_field(
            "reserved",
            StatusValue::parse(&payload).expect("reserved report payload must be valid JSON"),
        )
        .json()
}

/// One global flag that applies across commands.
pub const DRY_RUN_FLAG: &str = "--dry-run";
/// The one spelling that selects machine-readable command output.
pub const MACHINE_OUTPUT_FLAG: &str = "--json";
pub const CANVAS_FLAG: &str = "--canvas";


/// Jet flags whose value is the next argv word (`-p <member>`,
/// `--target <triple>`). That value is never a command, file, or job word.
pub fn flag_takes_separate_value(argument: &str) -> bool {
    matches!(
        argument,
        "-p" | "--fixtures"
            | "--env"
            | "--preset"
            | "--set"
            | "--builder"
            | "--output"
            | "--profile"
            | "--target"
            | "--endpoint"
            | "--channel"
            | "--platform"
            | "--trust-key"
            | "--gate"
            | "--allow"
            | "--deny"
            | "--scope"
            | "--live"
            | "--replay"
            | "--project"
            | "--console-ttl"
            | "--app"
            | "--share"
            | "--token"
            | "--base-receipt"
            | "--receipt"
            | "--head-receipt"
            | "--after-receipt"
            | "--canvas-host"
            | "--canvas-port"
            | "--canvas-transport"
            | "--canvas-authority"
            | "--where"
            | "--capture"
            | "--browser"
            | "--browser-retries"
            | "--browser-reporter"
            | "--filter"
            | "--shuffle"
            | "--verify"
            | "--template"
            | "--sort"
            | "--threads"
    )
}

/// D-JET-VERBS1=A / D-JOB-ARGV1=A: a project job owns every word
/// after the first command word. Call only after discovering that job.
pub fn separate_job_argv(args: &mut Vec<String>) {
    let mut index = 0;
    while index < args.len() {
        let argument = args[index].as_str();
        if argument == "--" { return; }
        if flag_takes_separate_value(argument) {
            index += 2;
        } else if argument.starts_with('-') && argument != "-" {
            index += 1;
        } else {
            let rest = index + 1;
            if rest < args.len() && args[rest] != "--" {
                args.insert(rest, "--".to_string());
            }
            return;
        }
    }
}

pub fn machine_output_requested(args: &[String]) -> bool {
    let args = before_argument_separator(args);
    args.iter().any(|arg| arg == MACHINE_OUTPUT_FLAG)
        || args.first().is_some_and(|arg| arg == "compiler")
        || args
            .windows(2)
            .any(|pair| pair[0] == "inspect" && pair[1] == "compiler")
}

#[derive(Clone)]
pub struct FlagSpec {
    /// Long form, e.g. `--json` (always present).
    pub long: &'static str,
    /// One-line help, used in completions and the man page.
    pub help: &'static str,
}


/// #1659 criterion 1 (round 2): groups are no longer a second parallel array —
/// they are the `COMMANDS` rows whose `actions` is non-empty. Every renderer
/// (dispatch, help, man, completions) reads this same one table.
pub fn command_groups() -> impl Iterator<Item = &'static CommandSpec> {
    COMMANDS.iter().filter(|c| c.is_group())
}

pub fn command_group(name: &str) -> Option<&'static CommandSpec> {
    command_groups().find(|group| group.name == name)
}

pub fn command_group_label(name: &str) -> String {
    name.split('-')
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().chain(chars).collect(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join("-")
}

/// Help-only summaries for commands whose output carries the application
/// effect projection. Man and completion descriptions stay the registry's
/// concise summaries; interactive and command help teach the four distinct
/// roles users will see in those reports.
pub fn action_help_summary(group: &str, action: &NestedCommandSpec) -> &'static str {
    match (group, action.name) {
        ("inspect", "rights") => {
            "Read required, granted, denied effects, and their authority source"
        }
        ("inspect", "claims") => "Read receipt-backed claims and their current status",
        ("inspect", "shapes") => "Read semantic shapes and their checked projections",
        ("inspect", "build") => "Read build identity, inputs, and provenance",
        ("inspect", "provenance") => {
            "Read dependency provenance with required, granted, denied effects, and authority"
        }
        ("inspect", "semindex") => {
            "Search code facts plus required, granted, denied effects, and authority"
        }
        ("inspect", "output") => {
            "Inspect one Output with required, granted, denied effects, and authority"
        }
        ("inspect", "gates") => {
            "Read gates with required, granted, denied effects, and authority"
        }
        ("inspect", "expand") => {
            "Show expanded meaning with required, granted, denied effects, and authority"
        }
        _ => action.summary,
    }
}

/// #1659 criterion 1: the one renderer for a group's usage block, shared by
/// `jet help`, `jet <group> --help`, and `jet perf --help` (CmdPerf.rs) so
/// every caller reads the same `COMMANDS` table instead of re-deriving text.
pub fn command_group_usage(name: &str) -> String {
    let Some(group) = command_group(name) else {
        return String::new();
    };
    let mut output = String::new();
    if let Some(usage) = group.usage {
        output.push_str(&format!(
            "  {} {:<48} {}\n",
            BINARY_NAME, usage, group.summary
        ));
    }
    for action in group.actions {
        let summary = action_help_summary(group.name, action);
        for usage in action.usage.lines() {
            output.push_str(&format!(
                "  {} {} {:<48} {}\n",
                BINARY_NAME, group.name, usage, summary
            ));
        }
    }
    output
}

pub fn nested_command(
    group: &str,
    action: &str,
) -> Option<(&'static CommandSpec, &'static NestedCommandSpec)> {
    let group = command_group(group)?;
    group
        .actions
        .iter()
        .find(|spec| spec.name == action)
        .map(|action| (group, action))
}

pub fn moved_command(name: &str) -> Option<(&'static CommandSpec, &'static NestedCommandSpec)> {
    // A nested action may share a word with a canonical top-level command
    // (`jet env test` and `jet test`). The canonical top-level intent wins
    // bare-word lookup; grouped dispatch still uses `nested_command` and keeps
    // the owning group when its handler requires it.
    // A group name itself has the same priority: `env` is both the canonical
    // environment front door and the `inspect env` action, so the group must
    // reach its own dispatcher before this moved-command teaching path.
    if command_group(name).is_some() {
        return None;
    }
    if COMMANDS.iter().any(|command| command.name == name) {
        return None;
    }
    if command_groups().any(|group| {
        group
            .actions
            .iter()
            .any(|action| action.name == name && action.also_canonical_top_level)
    }) {
        return None;
    }
    command_groups()
        .find_map(|group| {
            group
                .actions
                .iter()
                .find(|action| action.name == name)
                .map(|action| (group, action))
        })
        .filter(|(_, action)| {
            // E0043 reserves bare `install` for its teaching diagnostic even though
            // the real shared-store action is `jet shared-store install`.
            !action.also_canonical_top_level && action.name != "install"
        })
}

pub fn moved_command_group(name: &str) -> Option<&'static str> {
    moved_command(name).map(|(group, _)| group.name)
}


/// D-ONCE-RETIRE1=C: the one registry for retired command routes. These are
/// semantic retirements, so they hard-error with a teaching fix; they are not
/// aliases, rewrites, or help rows. Longest matching spelling wins so a
/// specific former subcommand can teach its exact current home.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RetirementCategory {
    Rename,
    Semantic,
}

pub struct RetiredCommandSpec {
    pub spelling: &'static str,
    pub category: RetirementCategory,
    pub error_code: &'static str,
    pub why: &'static str,
    pub fix: fn(&[String]) -> String,
    pub rewrite: Option<fn(&[String]) -> Vec<String>>,
}


fn retired_serve_fix(argv: &[String]) -> String {
    match argv.get(1).map(String::as_str) {
        Some(file) => format!("jet dev {file} --swap"),
        None => "jet dev <file.jet> --swap".to_string(),
    }
}

