    #[test]
    fn moved_command_registry_agrees_with_dispatch() {
        for group in command_groups() {
            for action in group.actions {
                if action.name == "install" {
                    assert_eq!(action.handler, HandlerKey::SharedStore);
                    assert!(moved_command(action.name).is_none());
                    continue;
                }
                if action.also_canonical_top_level {
                    assert!(is_canonical_top_level(action.name));
                    assert!(moved_command(action.name).is_none());
                    continue;
                }
                assert!(
                    !is_canonical_top_level(action.name),
                    "moved bare command leaked: {}",
                    action.name
                );
                let owner = moved_command_group(action.name);
                assert!(owner.is_some(), "missing moved owner for {}", action.name);
                // An action name can appear in more than one group (`export` under
                // multiple groups). Bare teaching routes to the first registered owner.
                assert!(
                    command_groups().any(|candidate| {
                        candidate.name == owner.unwrap()
                            && candidate
                                .actions
                                .iter()
                                .any(|entry| entry.name == action.name)
                    }),
                    "{} moved to unknown owner {:?}",
                    action.name,
                    owner
                );
            }
        }
    }

    #[test]
    fn typo_suggestions_never_advertise_moved_bare_actions() {
        for group in command_groups() {
            for action in group.actions {
                let canonical_bare = COMMANDS.iter().any(|command| {
                    command.name == action.name
                        && command.actions.is_empty()
                        && is_canonical_top_level(command.name)
                });
                if !action.also_canonical_top_level && !canonical_bare {
                    assert_ne!(closest_command(action.name), Some(action.name));
                }
            }
        }
    }

    #[test]
    fn every_nested_action_has_canonical_usage() {
        for group in command_groups() {
            for action in group.actions {
                assert!(
                    !action.usage.trim().is_empty(),
                    "missing usage for {} {}",
                    group.name,
                    action.name
                );
                for usage in action.usage.lines() {
                    assert!(
                        usage == action.name || usage.starts_with(&format!("{} ", action.name)),
                        "usage `{usage}` does not begin with action name `{}`",
                        action.name
                    );
                }
            }
        }
    }

    #[test]
    fn every_nested_action_routes_to_a_real_dispatch_seam() {
        for group in command_groups() {
            for action in group.actions {
                assert!(
                    !action.summary.trim().is_empty(),
                    "missing summary for {} {}",
                    group.name,
                    action.name
                );
                assert!(
                    is_builtin(action.handler.dispatch_word()),
                    "{} {} routes to missing handler {}",
                    group.name,
                    action.name,
                    action.handler.dispatch_word()
                );
                assert_eq!(
                    nested_command(group.name, action.name).map(|(_, value)| value.handler),
                    Some(action.handler)
                );
                if action.handler.keeps_group() {
                    assert_eq!(
                        action.handler.dispatch_word(),
                        group.name,
                        "kept group must own its dispatcher"
                    );
                }
                let mut normalized = vec![
                    group.name.to_string(),
                    action.name.to_string(),
                    "tail".to_string(),
                ];
                if !action.handler.keeps_group() {
                    normalized[0] = action.handler.dispatch_word().to_string();
                    normalized.remove(1);
                }
                let expected = if action.handler.keeps_group() {
                    vec![
                        group.name.to_string(),
                        action.name.to_string(),
                        "tail".to_string(),
                    ]
                } else {
                    vec![action.handler.dispatch_word().to_string(), "tail".to_string()]
                };
                assert_eq!(normalized, expected);
            }
        }
    }

